package connect

// ResultOf computes the winner of a Hex / Polygon game.
//
// Player "X" wins by connecting the left and right edges of the board, while
// player "O" wins by connecting the top and bottom edges. It returns "X", "O",
// or "" when neither player has made a connection yet.
func ResultOf(lines []string) (string, error) {
	height := len(lines)
	if height == 0 {
		return "", nil
	}

	// Neighbor offsets for a cell in the skewed (parallelogram) grid. The rows
	// are shifted relative to one another, so the diagonal neighbors are not
	// the symmetric set you would use for a square grid.
	neighbors := [6][2]int{
		{0, -1}, {0, 1},  // left, right
		{-1, 0}, {-1, 1}, // up-left, up-right
		{1, -1}, {1, 0},  // down-left, down-right
	}

	// connects reports whether `player` has a continuous path of stones running
	// from the start edge to the end edge.
	connects := func(player byte, onStart, onEnd func(r, c int) bool) bool {
		visited := make([][]bool, height)
		for r := range visited {
			visited[r] = make([]bool, len(lines[r]))
		}

		var stack [][2]int
		for r := 0; r < height; r++ {
			for c := 0; c < len(lines[r]); c++ {
				if lines[r][c] == player && onStart(r, c) {
					visited[r][c] = true
					stack = append(stack, [2]int{r, c})
				}
			}
		}

		for len(stack) > 0 {
			cell := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			r, c := cell[0], cell[1]
			if onEnd(r, c) {
				return true
			}
			for _, n := range neighbors {
				nr, nc := r+n[0], c+n[1]
				if nr < 0 || nr >= height || nc < 0 || nc >= len(lines[nr]) {
					continue
				}
				if visited[nr][nc] || lines[nr][nc] != player {
					continue
				}
				visited[nr][nc] = true
				stack = append(stack, [2]int{nr, nc})
			}
		}
		return false
	}

	if connects('X',
		func(r, c int) bool { return c == 0 },
		func(r, c int) bool { return c == len(lines[r])-1 }) {
		return "X", nil
	}
	if connects('O',
		func(r, c int) bool { return r == 0 },
		func(r, c int) bool { return r == height - 1 }) {
		return "O", nil
	}
	return "", nil
}
